import torch

def soft_dice(logits, targets, eps=1e-6):
    if logits.ndim < 4 or logits.shape[1] != 1:
        raise ValueError("expected binary logits with shape [B, 1, ...]")
    targets = torch.as_tensor(targets, device=logits.device)
    if targets.ndim == logits.ndim - 1:
        targets = targets.unsqueeze(1)
    if targets.shape != logits.shape:
        raise ValueError("targets must match logits, with an optional channel axis")
    if not bool(torch.isfinite(targets).all()):
        raise ValueError("targets contain a non-finite value")
    if bool(((targets < 0) | (targets > 1)).any()):
        raise ValueError("binary targets must lie in [0, 1]")

    probabilities = logits.sigmoid()
    targets = targets.to(dtype=probabilities.dtype)
    dims = tuple(range(1, probabilities.ndim))
    intersection = (probabilities * targets).sum(dim=dims)
    denominator = probabilities.sum(dim=dims) + targets.sum(dim=dims)
    return (2 * intersection + eps) / (denominator + eps)

def soft_dice_loss(logits, targets):
    return 1 - soft_dice(logits, targets).mean()

import torch

def window_to_rgb(slice_hu, low=-1000.0, high=400.0):
    if high <= low:
        raise ValueError("high must be greater than low")
    slice_hu = torch.as_tensor(slice_hu, dtype=torch.float32)
    if slice_hu.ndim != 2:
        raise ValueError("expected one CT slice with shape [H, W]")

    clipped = slice_hu.clamp(low, high)
    unit = (clipped - low) / (high - low)
    rgb = unit.unsqueeze(0).repeat(3, 1, 1)
    if rgb.amin().item() < 0 or rgb.amax().item() > 1:
        raise AssertionError("windowed values escaped [0, 1]")
    return rgb

import torch
from torchvision import tv_tensors
from torchvision.transforms import v2

transform = v2.Compose([
    v2.RandomHorizontalFlip(p=0.5),
    v2.RandomRotation(
        10,
        interpolation=v2.InterpolationMode.BILINEAR,
        fill={tv_tensors.Image: 0, tv_tensors.Mask: 0},
    ),
    v2.ToDtype({
        tv_tensors.Image: torch.float32,
        tv_tensors.Mask: torch.int64,
        "others": None,
    }, scale=True),
])

def augment_pair(image_uint8, mask_uint8):
    image = tv_tensors.Image(image_uint8)
    mask = tv_tensors.Mask(mask_uint8)
    allowed_ids = set(mask.unique().tolist()) | {0}
    image, mask = transform(image, mask)

    if image.shape[-2:] != mask.shape[-2:]:
        raise AssertionError("image and mask geometry diverged")
    if mask.dtype != torch.int64:
        raise AssertionError("mask class IDs must remain integer-valued")
    if not set(mask.unique().tolist()).issubset(allowed_ids):
        raise AssertionError("interpolation introduced a new mask class ID")
    return image, mask
